  assert(text('forecastTarget') "'!== '"'—', 'forecast target missing');
  assert(text('heroHorizon') === '60 trading days', 'default horizon wrong');
  assert(document.querySelectorAll('#priceChart path').length >= 3, 'main SVG paths missing');
  assert(document.querySelectorAll('#validationChart path').length >= 3, 'validation SVG paths missing');
  assert(Number(text('caseMetric')) > 10, 'backtest cases missing');
  const baseTarget = Number(text('forecastTarget').replace(/,/g,''));
  document.querySelector('[data-scenario=\"bear\"]').click();
  const bearTarget = Number(text('forecastTarget').replace(/,/g,''));
  assert(bearTarget < baseTarget, 'bear scenario did not lower target');
  document.querySelector('[data-scenario=\"bull\"]').click();
  const bullTarget = Number(text('forecastTarget').replace(/,/g,''));
  assert(bullTarget > baseTarget, 'bull scenario did not raise target');
  document.querySelector('[data-model=\"damped\"]').click();
  assert(document.querySelector('[data-model=\"damped\"]').classList.contains('active'), 'model selection did not activate');
  document.querySelector('[data-confidence=\"95\"]').click();
  assert(text('rangeLabel') === '95% MODEL RANGE', 'confidence label did not update');
  assert(text('coverageLabel') === 'inside 95% range', 'coverage label did not update');
  const slider = document.getElementById('horizonSlider');
  slider.value = '120';
  slider.dispatchEvent(new window.Event('input', { bubbles: true }));
  assert(text('heroHorizon') === '120 trading days', 'slider did not update horizon');
  document.querySelector('[data-range=\"all\"]').click();
  assert(document.querySelector('[data-range=\"all\"]').classList.contains('active'), 'chart range did not activate');
  document.getElementById('resetButton').click();
  assert(text('heroHorizon') === '60 trading days', 'reset did not restore horizon');
  assert(document.querySelector('[data-model=\"ensemble\"]').classList.contains('active'), 'reset did not restore model');
  assert(document.querySelector('[data-scenario=\"base\"]').classList.contains('active'), 'reset did not restore scenario');
  console.log(JSON.stringify({
    lastClose: text('lastClose'),
    baseTarget,
    bearTarget,
    bullTarget,
    backtestCases: text('caseMetric'),
    chartPaths: document.querySelectorAll('#priceChart path').length,
    validationPaths: document.querySelectorAll('#validationChart path').length
  }, null, 2));
  console.log('DOM_INTERACTION_VALIDATION_OK');
})().catch(error => { console.error(error.stack); process.exit(1); });
