const fs = require('node:fs');
const { JSDOM } = require('jsdom');
(async () => {
  const dom = new JSDOM(fs.readFileSync('index.html', 'utf8'), { runScripts: 'outside-only', url: 'http://127.0.0.1:8765/' });
  await new Promise(resolve => setImmediate(resolve));
  const w = dom.window;
  w.eval(fs.readFileSync('data.js', 'utf8'));
  w.eval(fs.readFileSync('app.js', 'utf8'));
  const d = w.document;
  const assert = (ok, msg) => { if ("'!ok) throw new Error(msg); };
  const text = id => d.getElementById(id).textContent.trim();
  assert(text('"'lastClose') === '7,749', 'summary render failed');
  assert(d.querySelectorAll('#priceChart path').length >= 3, 'forecast chart missing');
  assert(d.querySelectorAll('#validationChart path').length >= 3, 'validation chart missing');
  const base = Number(text('forecastTarget').replace(/,/g, ''));
  d.querySelector('[data-scenario=\"bear\"]').click();
  const bear = Number(text('forecastTarget').replace(/,/g, ''));
  d.querySelector('[data-scenario=\"bull\"]').click();
  const bull = Number(text('forecastTarget').replace(/,/g, ''));
  assert(bear < base && base < bull, 'scenario ordering failed');
  d.querySelector('[data-model=\"damped\"]').click();
  d.querySelector('[data-confidence=\"95\"]').click();
  assert(text('rangeLabel') === '95% MODEL RANGE', 'confidence control failed');
  const slider = d.getElementById('horizonSlider');
  slider.value = '120';
  slider.dispatchEvent(new w.Event('input', { bubbles: true }));
  assert(text('heroHorizon') === '120 trading days', 'horizon slider failed');
  d.querySelector('[data-range=\"all\"]').click();
  assert(d.querySelector('[data-range=\"all\"]').classList.contains('active'), 'range control failed');
  d.getElementById('resetButton').click();
  assert(text('heroHorizon') === '60 trading days', 'reset failed');

  const csv = ['observation_date,SP500'].concat(w.SP500_DATA.slice(0, 350).map(r => r.join(','))).join('\\n');
  const input = d.getElementById('csvInput');
  Object.defineProperty(input, 'files', { configurable: true, value: [{ name: 'sample.csv', text: () => Promise.resolve(csv) }] });
  input.dispatchEvent(new w.Event('change', { bubbles: true }));
  await new Promise(resolve => setTimeout(resolve, 20));
  assert(text('observationCount') === '350 daily observations', 'CSV import failed: '+text('observationCount'));
  assert(d.getElementById('sourceLink').textContent.includes('sample.csv'), 'custom source did not update');
  d.getElementById('restoreData').click();
  assert(text('observationCount') === '2,164 daily observations', 'data restore failed');

  let downloadName = '';
  w.URL.createObjectURL = () => 'blob:test';
  w.URL.revokeObjectURL = () => {};
  w.HTMLAnchorElement.prototype.click = function () { downloadName = this.download; };
  d.getElementById('exportButton').click();
  assert(/"'^sp500-forecast-2026-08-12-60d'"\\.csv"'$/.test(downloadName), '"'export filename failed: '+downloadName);

  console.log(JSON.stringify({ lastClose:text('lastClose'), base, bear, bull, cases:text('caseMetric'), imported:350, export:downloadName }, null, 2));
  console.log('FULL_DOM_INTERACTION_VALIDATION_OK');
})().catch(error => { console.error(error.stack); process.exit(1); });
NODE"

